for code, d in D.items():
    lines = ["import type { PageTranslations } from './types'", "", f"export const {code}: PageTranslations = {{", "  purposes: {"]
    for k in PURPOSE_KEYS:
        v = d['purposes'].get(k, k).replace('\\', '\\\\').replace("'", "\\'")
        lines.append(f"    {k}: '{v}',")
    lines.append("  },")
    lines.append("  policies: {")
    for k in POLICY_KEYS:
        v = d['policies'].get(k, k).replace('\\', '\\\\').replace("'", "\\'")
        lines.append(f"    {k}: '{v}',")
    lines.append("  },")
    lines.append("}")
    path = os.path.join(DIR, f"{code}.ts")
    with open(path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines) + '\n')
    print(f"Created {code}.ts")
